svg.script:
(function(){
  var current = null;
  var root = document.currentScript.parentNode;
  root.addEventListener('click', function(e){
    var t = e.target.closest('#provinces > path');
    if (!t) return;
    if (current === t) {
      t.classList.remove('selected'); current = null;
    } else {
      if (current) current.classList.remove('selected');
      t.classList.add('selected'); current = t;
    }
    root.dispatchEvent(new CustomEvent('provinceSelected', {
      detail: { id: current && current.id, element: current }
    }));
  });
})();
